import os
import google.generativeai as genai

def moderate_batch(payload, config=None):
    config = config or {}
    api_key = os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY environment variable not set.")
    genai.configure(api_key=api_key)

    model = genai.GenerativeModel('gemini-1.5-flash-latest')

    batch_results = []
    for message in payload:
        # The GenerativeModel's `generate_content` call inherently includes safety checks.
        # We simulate a "moderation decision" by checking the `prompt_feedback.safety_ratings`
        # which indicates if any safety category was blocked.
        # This is not a dedicated moderation API, but rather the built-in safety features
        # of the generative model.

        try:
            response = model.generate_content(
                message,
                safety_settings=[
                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_ONLY_HIGH"},
                ]
            )

            # Check if any safety rating indicates the content was blocked.
            # If the response is blocked, access `prompt_feedback`. If not, it will be None or empty.
            if response.prompt_feedback and response.prompt_feedback.safety_ratings:
                blocked = any(
                    rating.blocked for rating in response.prompt_feedback.safety_ratings
                )
                if blocked:
                    batch_results.append({"message": message, "decision": "BLOCKED", "details": [
                        {"category": rating.category.name, "probability": rating.probability.name, "blocked": rating.blocked}
                        for rating in response.prompt_feedback.safety_ratings
                    ]})
                else:
                    batch_results.append({"message": message, "decision": "APPROVED", "details": "Content generated successfully or passed safety checks."})
            else:
                # If prompt_feedback is not present or no safety ratings, it means it passed.
                # Or, if `candidates` is empty, it means it was blocked.
                if not response.candidates:
                     batch_results.append({"message": message, "decision": "BLOCKED", "details": "Content was blocked without explicit prompt_feedback (e.g., due to internal reasons or very high severity blocking)."})
                else:
                    batch_results.append({"message": message, "decision": "APPROVED", "details": "Content generated successfully or passed safety checks."})

        except Exception as e:
            # Handle cases where the API call itself fails, or content is blocked
            # in a way that raises an exception (e.g., due to safety).
            # The client library might raise an exception for blocked content.
            if "The prompt was blocked" in str(e) or "Safety setting" in str(e):
                batch_results.append({"message": message, "decision": "BLOCKED", "details": f"API call failed due to safety reasons: {e}"})
            else:
                batch_results.append({"message": message, "decision": "ERROR", "details": f"An error occurred during moderation: {e}"})
    result = {"moderation_results": batch_results}
    return result
